package com.osrsjournal;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Captures obtained Collection Log items when the player opens a log page.
 *
 * <p>Listens for {@link ScriptID#COLLECTION_DRAW_LIST} (same hook as Chat
 * Commands' pets tracker), reads the page title + item widgets, and
 * accumulates pages until {@link #drainPages()} is called by the sync path.
 */
@Slf4j
@Singleton
class CollectionLogCapture
{
	/** Title child on {@link InterfaceID.Collection#HEADER_TEXT} (ChatCommands uses 0). */
	private static final int HEADER_TITLE_CHILD = 0;

	private final Client client;

	/** Pages changed since the last drain — keyed by page title. */
	private final Map<String, List<CapturedItem>> pending = new LinkedHashMap<>();

	private Runnable onPagesChanged;

	@Inject
	CollectionLogCapture(Client client)
	{
		this.client = client;
	}

	void setOnPagesChanged(Runnable onPagesChanged)
	{
		this.onPagesChanged = onPagesChanged;
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() != ScriptID.COLLECTION_DRAW_LIST)
		{
			return;
		}

		Widget header = client.getWidget(InterfaceID.Collection.HEADER_TEXT);
		if (header == null || header.getChildren() == null)
		{
			return;
		}

		Widget titleWidget = header.getChild(HEADER_TITLE_CHILD);
		if (titleWidget == null)
		{
			return;
		}
		String page = titleWidget.getText();
		if (page == null || page.isEmpty())
		{
			return;
		}
		page = Text.removeTags(page).replace('\u00A0', ' ').trim();
		if (page.isEmpty())
		{
			return;
		}

		Widget itemsRoot = client.getWidget(InterfaceID.Collection.ITEMS_CONTENTS);
		List<CapturedItem> obtained = new ArrayList<>();
		if (itemsRoot != null && itemsRoot.getChildren() != null)
		{
			for (Widget child : itemsRoot.getChildren())
			{
				if (child == null || child.getOpacity() != 0)
				{
					continue;
				}
				int itemId = child.getItemId();
				if (itemId <= 0)
				{
					continue;
				}
				String name = cleanItemName(child.getName());
				int qty = child.getItemQuantity();
				if (qty <= 0)
				{
					qty = 1;
				}
				obtained.add(new CapturedItem(itemId, name, qty));
			}
		}

		synchronized (pending)
		{
			pending.put(page, obtained);
		}
		log.debug("Collection log page '{}' — {} obtained item(s)", page, obtained.size());

		Runnable cb = onPagesChanged;
		if (cb != null)
		{
			cb.run();
		}
	}

	/**
	 * Returns and clears pages captured since the last drain.
	 * Safe to call from any thread; capture writes happen on the client thread.
	 */
	Map<String, List<CapturedItem>> drainPages()
	{
		synchronized (pending)
		{
			if (pending.isEmpty())
			{
				return Collections.emptyMap();
			}
			Map<String, List<CapturedItem>> out = new LinkedHashMap<>(pending);
			pending.clear();
			return out;
		}
	}

	boolean hasPending()
	{
		synchronized (pending)
		{
			return !pending.isEmpty();
		}
	}

	private static String cleanItemName(String raw)
	{
		if (raw == null || raw.isEmpty())
		{
			return "";
		}
		return Text.removeTags(raw).replace('\u00A0', ' ').trim();
	}

	/** Obtained item on a collection-log page. */
	static final class CapturedItem
	{
		private final int itemId;
		private final String itemName;
		private final int quantity;

		CapturedItem(int itemId, String itemName, int quantity)
		{
			this.itemId = itemId;
			this.itemName = itemName != null ? itemName : "";
			this.quantity = quantity;
		}

		int getItemId()
		{
			return itemId;
		}

		String getItemName()
		{
			return itemName;
		}

		int getQuantity()
		{
			return quantity;
		}
	}
}

package com.osrsjournal;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;

/**
 * Item containers that are only populated when the player opens them — looting
 * bag (Check) and Player-Owned House costume-room storage. Numeric IDs match
 * {@code net.runelite.api.gameval.InventoryID}. Each key is replaced independently
 * so opening the armour case cannot wipe a previously synced cape rack.
 */
final class ExtraItemStorage
{
    static final String LOOTING_BAG = "looting_bag";

    private static final Map<Integer, String> BY_ID;

    static
    {
        Map<Integer, String> ids = new LinkedHashMap<>();
        ids.put(516, LOOTING_BAG);
        ids.put(446, "poh_magic_wardrobe");
        ids.put(447, "poh_armour");
        ids.put(448, "poh_fancy_dress");
        ids.put(449, "poh_treasure_1");
        ids.put(450, "poh_treasure_2");
        ids.put(451, "poh_treasure_3");
        ids.put(452, "poh_capes");
        ids.put(453, "poh_holiday");
        ids.put(485, "poh_treasure_1a");
        ids.put(486, "poh_treasure_2a");
        ids.put(487, "poh_treasure_3a");
        ids.put(488, "poh_capes_2");
        ids.put(627, "poh_treasure_0");
        BY_ID = Collections.unmodifiableMap(ids);
    }

    private ExtraItemStorage()
    {
    }

    static boolean isTracked(int containerId)
    {
        return BY_ID.containsKey(containerId);
    }

    static String keyFor(int containerId)
    {
        return BY_ID.get(containerId);
    }

    static Set<Integer> containerIds()
    {
        return BY_ID.keySet();
    }

    static boolean isAllowedKey(String key)
    {
        return key != null && BY_ID.containsValue(key);
    }
}

package com.osrsjournal;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * HTTP client for the hosted Supabase Edge Functions (multi-user mode).
 *
 * <p>The plugin deliberately holds no database credentials: every write goes
 * through an Edge Function that validates the per-character sync token
 * ({@code X-Sync-Token}) server-side and performs the actual database work with
 * the service role. Endpoints used:
 * <ul>
 *   <li>{@code pair-init} — issue/reuse a sync token + pairing code for an RSN</li>
 *   <li>{@code sync} — batched upsert of skills/quests/equipment/bank/inventory/stashes/collection log</li>
 *   <li>{@code localhost-session} — short-lived read token for "Open full journal"</li>
 * </ul>
 *
 * <p>Uses RuneLite's injected {@link OkHttpClient}; all calls are synchronous and
 * must run on the shared executor, never the client thread.
 */
@Slf4j
@Singleton
public class HostedApiService
{
    private static final MediaType JSON_MEDIA = MediaType.get("application/json; charset=utf-8");

    @Inject
    private OkHttpClient httpClient;

    @Inject
    private Gson gson;

    @Inject
    private OsrsJournalConfig config;

    /** Production endpoints by default; self-hosters can override in Advanced config. */
    String resolveApiBase()
    {
        return JournalConstants.resolveApiBase(config.apiBaseUrl());
    }

    /**
     * Requests a pairing code + sync token for {@code rsn}.
     * Returns null on any failure — callers treat that as "pairing unavailable"
     * and retry later (rate limits on the server make hammering pointless).
     */
    PairingState pairInit(String rsn)
    {
        String base = resolveApiBase();

        JsonObject body = new JsonObject();
        body.addProperty("rsn", rsn);

        Request.Builder builder = new Request.Builder()
            .url(base + "/pair-init")
            .post(RequestBody.create(JSON_MEDIA, body.toString()))
            .header("Content-Type", "application/json");

        addPluginClientId(builder);

        try (Response response = httpClient.newCall(builder.build()).execute())
        {
            if (!response.isSuccessful() || response.body() == null)
            {
                log.warn("pair-init failed for '{}': HTTP {}", rsn, response.code());
                return null;
            }

            JsonObject json = gson.fromJson(response.body().string(), JsonObject.class);
            if (json == null || !json.has("code") || !json.has("sync_token")
                || json.get("code").isJsonNull() || json.get("sync_token").isJsonNull())
            {
                log.warn("pair-init returned incomplete JSON for '{}'", rsn);
                return null;
            }

            return new PairingState(
                rsn,
                json.get("code").getAsString(),
                json.get("sync_token").getAsString(),
                json.has("linked") && json.get("linked").getAsBoolean(),
                json.has("expires_in") ? json.get("expires_in").getAsInt() : 600
            );
        }
        catch (IOException | RuntimeException e)
        {
            log.error("pair-init error for '{}'", rsn, e);
            return null;
        }
    }

    /**
     * Exchanges the sync token for a ~5 minute read-only session token, so
     * "Open full journal" can show bank/gear in the browser without the user
     * signing in. Returns null if the exchange fails (caller falls back to the
     * public profile URL).
     */
    String createLocalhostSession(String syncToken)
    {
        String base = resolveApiBase();
        if (syncToken == null || syncToken.isEmpty())
        {
            return null;
        }

        Request request = new Request.Builder()
            .url(base + "/localhost-session")
            .post(RequestBody.create(JSON_MEDIA, "{}"))
            .header("Content-Type", "application/json")
            .header("X-Sync-Token", syncToken)
            .build();

        try (Response response = httpClient.newCall(request).execute())
        {
            if (!response.isSuccessful() || response.body() == null)
            {
                log.warn("localhost-session failed: HTTP {}", response.code());
                return null;
            }

            JsonObject json = gson.fromJson(response.body().string(), JsonObject.class);
            if (json == null || !json.has("session_token") || json.get("session_token").isJsonNull())
            {
                log.warn("localhost-session returned incomplete JSON");
                return null;
            }
            return json.get("session_token").getAsString();
        }
        catch (IOException | RuntimeException e)
        {
            log.error("localhost-session error", e);
            return null;
        }
    }

    /**
     * Posts a batched sync payload. One request carries any combination of
     * players/skills/quests/equipment/bank/inventory/collection-log rows — the
     * server upserts them in FK-safe order and answers with {@code claimed},
     * which doubles as a free "is this character linked yet?" check on every sync.
     */
    SyncResult sync(String rsn, String syncToken, SyncPayload payload)
    {
        String base = resolveApiBase();
        if (syncToken == null || syncToken.isEmpty())
        {
            return SyncResult.failed(false, "No sync token");
        }

        payload.setRsn(rsn);

        Request request = new Request.Builder()
            .url(base + "/sync")
            .post(RequestBody.create(JSON_MEDIA, gson.toJson(payload)))
            .header("Content-Type", "application/json")
            .header("X-Sync-Token", syncToken)
            .build();

        try (Response response = httpClient.newCall(request).execute())
        {
            if (!response.isSuccessful())
            {
                String detail = "HTTP " + response.code();
                log.warn("hosted sync failed for '{}': {}", rsn, detail);
                // 401/403 means the stored token is stale (e.g. rotated server-side)
                boolean authFailed = response.code() == 401 || response.code() == 403;
                if (response.code() == 429)
                {
                    return SyncResult.failed(false, "Rate limited — try again shortly");
                }
                return SyncResult.failed(authFailed, detail);
            }

            boolean claimed = false;
            List<String> warnings = Collections.emptyList();
            if (response.body() != null)
            {
                try
                {
                    JsonObject json = gson.fromJson(response.body().string(), JsonObject.class);
                    if (json != null)
                    {
                        claimed = json.has("claimed") && json.get("claimed").getAsBoolean();
                        warnings = readWarnings(json);
                    }
                }
                catch (RuntimeException e)
                {
                    log.debug("could not parse sync response for '{}'", rsn, e);
                }
            }
            if (!warnings.isEmpty())
            {
                log.warn("hosted sync for '{}' returned warnings: {}", rsn, warnings);
                return SyncResult.okWithWarnings(claimed, warnings);
            }
            log.debug("hosted sync ok for '{}' (claimed={})", rsn, claimed);
            return SyncResult.ok(claimed);
        }
        catch (IOException e)
        {
            log.error("hosted sync error for '{}'", rsn, e);
            return SyncResult.failed(false, e.getMessage() != null ? e.getMessage() : "Network error");
        }
    }

    private static List<String> readWarnings(JsonObject json)
    {
        if (!json.has("warnings") || !json.get("warnings").isJsonArray())
        {
            return Collections.emptyList();
        }
        JsonArray arr = json.getAsJsonArray("warnings");
        List<String> out = new ArrayList<>(arr.size());
        for (JsonElement el : arr)
        {
            if (el != null && el.isJsonPrimitive())
            {
                out.add(el.getAsString());
            }
        }
        return out;
    }

    /** Outcome of a sync call, including the server-reported pairing state. */
    static final class SyncResult
    {
        private final boolean success;
        private final boolean claimed;
        private final boolean authFailed;
        private final List<String> warnings;
        private final String error;

        private SyncResult(
            boolean success,
            boolean claimed,
            boolean authFailed,
            List<String> warnings,
            String error
        )
        {
            this.success = success;
            this.claimed = claimed;
            this.authFailed = authFailed;
            this.warnings = warnings != null ? warnings : Collections.emptyList();
            this.error = error;
        }

        static SyncResult ok(boolean claimed)
        {
            return new SyncResult(true, claimed, false, Collections.emptyList(), null);
        }

        static SyncResult okWithWarnings(boolean claimed, List<String> warnings)
        {
            return new SyncResult(true, claimed, false, warnings, null);
        }

        static SyncResult failed(boolean authFailed)
        {
            return failed(authFailed, null);
        }

        static SyncResult failed(boolean authFailed, String error)
        {
            return new SyncResult(false, false, authFailed, Collections.emptyList(), error);
        }

        boolean isSuccess()
        {
            return success;
        }

        /** True when the server confirmed this character is linked to a website account. */
        boolean isClaimed()
        {
            return claimed;
        }

        /** True when the request was rejected because the sync token is invalid/stale. */
        boolean isAuthFailed()
        {
            return authFailed;
        }

        boolean hasWarnings()
        {
            return !warnings.isEmpty();
        }

        List<String> getWarnings()
        {
            return warnings;
        }

        String getError()
        {
            return error;
        }
    }

    private void addPluginClientId(Request.Builder builder)
    {
        String clientId = config.pluginClientId();
        if (clientId == null || clientId.isEmpty())
        {
            clientId = JournalConstants.DEFAULT_PLUGIN_CLIENT_ID;
        }
        builder.header("X-Plugin-Client-Id", clientId);
    }

    /**
     * Request body for {@code /sync}, serialized by Gson — field names match the
     * Edge Function's expected JSON keys exactly (hence snake_case).
     * {@code replace_*} flags make equipment/bank/inventory a full replace so
     * removed items disappear; skills/quests are plain upserts.
     */
    static class SyncPayload
    {
        private String rsn;
        private List<Map<String, Object>> players;
        private List<Map<String, Object>> player_skills;
        private List<Map<String, Object>> player_quests;
        private List<Map<String, Object>> player_equipment;
        private List<Map<String, Object>> player_bank;
        private List<Map<String, Object>> player_diaries;
        private List<Map<String, Object>> player_combat_achievements;
        /** Inventory snapshot → player_inventory (counted with bank on the site). */
        private List<Map<String, Object>> inventory_tracked;
        /** Collection-log pages → player_collection_log (atomic replace per page). */
        private List<Map<String, Object>> collection_log_pages;
        /** Extra storage → player_item_stashes (looting bag / POH; replace per container). */
        private List<Map<String, Object>> player_stashes;
        private boolean replace_equipment;
        private boolean replace_bank;
        private boolean replace_inventory;
        private boolean touch_last_synced = true;
        private Boolean profile_public;

        void setRsn(String rsn)
        {
            this.rsn = rsn;
        }

        SyncPayload players(List<Map<String, Object>> records)
        {
            this.players = records;
            return this;
        }

        SyncPayload skills(List<Map<String, Object>> records)
        {
            this.player_skills = records;
            return this;
        }

        SyncPayload quests(List<Map<String, Object>> records)
        {
            this.player_quests = records;
            return this;
        }

        SyncPayload equipment(List<Map<String, Object>> records, boolean replace)
        {
            this.player_equipment = records;
            this.replace_equipment = replace;
            return this;
        }

        SyncPayload bank(List<Map<String, Object>> records, boolean replace)
        {
            this.player_bank = records;
            this.replace_bank = replace;
            return this;
        }

        /** Inventory snapshot written to player_inventory by /sync. */
        SyncPayload inventory(List<Map<String, Object>> records)
        {
            this.inventory_tracked = records != null ? records : Collections.emptyList();
            this.replace_inventory = true;
            return this;
        }

        /** Bank + inventory in one request so the site never sees a half update. */
        SyncPayload bankAndInventory(
            List<Map<String, Object>> bankRecords,
            List<Map<String, Object>> inventoryRecords
        )
        {
            this.player_bank = bankRecords != null ? bankRecords : Collections.emptyList();
            this.replace_bank = true;
            this.inventory_tracked = inventoryRecords != null ? inventoryRecords : Collections.emptyList();
            this.replace_inventory = true;
            return this;
        }

        SyncPayload diaries(List<Map<String, Object>> records)
        {
            this.player_diaries = records;
            return this;
        }

        SyncPayload combatAchievements(List<Map<String, Object>> records)
        {
            this.player_combat_achievements = records;
            return this;
        }

        /**
         * Collection-log page snapshots. Each entry is
         * {@code { page, items: [{ item_id, item_name, quantity }] }}.
         */
        SyncPayload collectionLogPages(List<Map<String, Object>> pages)
        {
            this.collection_log_pages = pages != null ? pages : Collections.emptyList();
            return this;
        }

        /**
         * Extra storage snapshots. Each entry is
         * {@code { container, items: [{ item_id, item_name, quantity }] }}.
         */
        SyncPayload stashes(List<Map<String, Object>> pages)
        {
            this.player_stashes = pages != null ? pages : Collections.emptyList();
            return this;
        }

        SyncPayload touchLastSynced(boolean touch)
        {
            this.touch_last_synced = touch;
            return this;
        }

        SyncPayload profilePublic(boolean isPublic)
        {
            this.profile_public = isPublic;
            return this;
        }
    }
}

package com.osrsjournal;

import java.io.UnsupportedEncodingException;
import java.net.URLEncoder;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.LinkBrowser;

/**
 * Opens the hosted web journal, with a short-lived live session when the
 * character has a sync token.
 */
@Slf4j
@Singleton
class JournalBrowser
{
    @Inject
    private JournalSyncService journalSyncService;

    @Inject
    private HostedApiService hostedApiService;

    @Inject
    private OsrsJournalConfig config;

    @Inject
    JournalBrowser()
    {
    }

    /**
     * Opens the journal in the browser. Performs network I/O (localhost-session
     * exchange) only when sync is opted in — must be called off the client/Swing threads.
     *
     * @return a short status message describing what happened, for the sidebar.
     */
    String openInBrowser(String rsn)
    {
        String sessionToken = null;
        boolean sessionFailed = false;
        // Session exchange hits the 3rd-party API — require the same opt-in as sync.
        if (rsn != null && config.syncEnabled())
        {
            String syncToken = journalSyncService.getSyncToken(rsn);
            if (syncToken != null)
            {
                sessionToken = hostedApiService.createLocalhostSession(syncToken);
                sessionFailed = sessionToken == null || sessionToken.isEmpty();
            }
        }

        String url = JournalConstants.WEB_APP_URL;
        if (sessionToken != null && !sessionToken.isEmpty())
        {
            url += "?local_session=" + sessionToken;
        }
        else if (rsn != null && !rsn.isEmpty())
        {
            // Fallback: at least load this character's profile on the site.
            url += "?rsn=" + urlEncode(rsn);
        }
        LinkBrowser.browse(url);

        if (!config.syncEnabled())
        {
            return "Opened journal (sync off — sign in on the site for full data).";
        }
        if (sessionFailed)
        {
            log.warn("OSRS Journal: live session unavailable for '{}' — opened profile view instead", rsn);
            return "Couldn't start a live session — opened your profile instead.";
        }
        if (sessionToken != null && !sessionToken.isEmpty())
        {
            return "Journal opened with a live session (~5 min).";
        }
        return "Journal opened in your browser.";
    }

    private static String urlEncode(String value)
    {
        try
        {
            return URLEncoder.encode(value, "UTF-8");
        }
        catch (UnsupportedEncodingException e)
        {
            return value;
        }
    }
}

package com.osrsjournal;

/**
 * Built-in production endpoints — Plugin Hub users never configure these.
 *
 * <p>Deliberately contains no database keys: the plugin talks only to Edge
 * Functions, which authenticate each request with the per-character sync token.
 * These URLs are public knowledge (they're visible in the website's own config),
 * so shipping them in the jar exposes nothing.
 */
public final class JournalConstants
{
    public static final String WEB_APP_URL = "https://journal.osrsjournal.com";
    public static final String PRIVACY_URL = WEB_APP_URL + "/privacy.html";

    public static final String SUPABASE_PROJECT_URL =
        "https://ahutsqmyahyxmrocrmwd.supabase.co";

    public static final String API_BASE_URL =
        SUPABASE_PROJECT_URL + "/functions/v1";

    /**
     * Sent as {@code X-Plugin-Client-Id} on pair-init. Not a secret (it ships in
     * the public jar) — it just lets the backend reject naive scripted abuse
     * that doesn't bother mimicking the plugin. Self-hosters can override it in
     * the Advanced config.
     */
    public static final String DEFAULT_PLUGIN_CLIENT_ID =
        "bdc873d042e7467bbd58223828c05662";

    private JournalConstants()
    {
    }

    /**
     * Returns the self-hosted override if the user set one, else production.
     * Accepts a Supabase REST URL by mistake ({@code .../rest/v1}) and rewrites
     * it to the functions endpoint, since that's the most common copy-paste error.
     */
    static String resolveApiBase(String configured)
    {
        if (configured != null && !configured.trim().isEmpty())
        {
            return normalizeApiBase(configured.trim());
        }
        return API_BASE_URL;
    }

    private static String normalizeApiBase(String url)
    {
        String trimmed = url;
        while (trimmed.endsWith("/"))
        {
            trimmed = trimmed.substring(0, trimmed.length() - 1);
        }
        if (trimmed.endsWith("/rest/v1"))
        {
            return trimmed.substring(0, trimmed.length() - "/rest/v1".length()) + "/functions/v1";
        }
        return trimmed;
    }
}

package com.osrsjournal;

import java.util.ArrayList;
import java.util.List;
import lombok.Getter;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

/**
 * Immutable view-model for the sidebar panel.
 *
 * <p>Built on the <em>client thread</em> via {@link #fromClient} (the only place
 * the RuneLite {@code Client} API may be read), then handed to Swing untouched —
 * so the panel never needs to reach back into game state from the EDT.
 */
@Getter
class JournalSnapshot
{
    private final String rsn;
    private final int combatLevel;
    private final int questPoints;
    private final int totalLevel;
    private final int questsFinished;
    private final List<SkillRow> skills;
    private final List<String> recentQuests;
    private final boolean syncEnabled;
    private final boolean bankSyncEnabled;
    private final boolean publicProfileEnabled;
    private final String pairCode;
    private final boolean accountLinked;
    private final boolean pairCodeExpired;
    private final String pairExpiryLabel;
    private final JournalSyncService.SyncStatus syncStatus;

    JournalSnapshot(
        String rsn,
        int combatLevel,
        int questPoints,
        int totalLevel,
        int questsFinished,
        List<SkillRow> skills,
        List<String> recentQuests,
        boolean syncEnabled,
        boolean bankSyncEnabled,
        boolean publicProfileEnabled,
        String pairCode,
        boolean accountLinked,
        boolean pairCodeExpired,
        String pairExpiryLabel,
        JournalSyncService.SyncStatus syncStatus
    )
    {
        this.rsn = rsn;
        this.combatLevel = combatLevel;
        this.questPoints = questPoints;
        this.totalLevel = totalLevel;
        this.questsFinished = questsFinished;
        this.skills = skills;
        this.recentQuests = recentQuests;
        this.syncEnabled = syncEnabled;
        this.bankSyncEnabled = bankSyncEnabled;
        this.publicProfileEnabled = publicProfileEnabled;
        this.pairCode = pairCode;
        this.accountLinked = accountLinked;
        this.pairCodeExpired = pairCodeExpired;
        this.pairExpiryLabel = pairExpiryLabel;
        this.syncStatus = syncStatus;
    }

    /** One-line status for the panel header, ordered by what the user should do next. */
    String getStatusText()
    {
        if (!syncEnabled)
        {
            return "Sync off — turn on Enable Sync in plugin settings (confirm the 3rd-party warning).";
        }
        if (syncStatus != null && syncStatus.getKind() == JournalSyncService.SyncStatus.Kind.ERROR
            && syncStatus.getMessage() != null)
        {
            return "Sync error: " + syncStatus.getMessage();
        }
        if (pairCodeExpired)
        {
            return "Pairing code expired — click New code, then enter it on the website.";
        }
        if (pairCode != null && !pairCode.isEmpty() && !accountLinked)
        {
            String expiry = pairExpiryLabel != null ? " (" + pairExpiryLabel + ")" : "";
            return "Link your account on journal.osrsjournal.com" + expiry;
        }
        if (syncStatus != null && syncStatus.getKind() == JournalSyncService.SyncStatus.Kind.WARNING
            && syncStatus.getMessage() != null)
        {
            return "Synced with warnings — " + syncStatus.getMessage();
        }
        if (accountLinked)
        {
            if (syncStatus != null && syncStatus.getKind() == JournalSyncService.SyncStatus.Kind.OK)
            {
                String age = syncStatus.getAgeLabel();
                return "Linked · " + syncStatus.getMessage() + (age != null ? " · " + age : "");
            }
            return "Linked · syncing to OSRS Journal cloud.";
        }
        return "Waiting for pairing — click New code if none appears.";
    }

    /** True when bank toggle is on but master sync is off (no-op trap). */
    boolean isBankSyncIneffective()
    {
        return bankSyncEnabled && !syncEnabled;
    }

    static class SkillRow
    {
        private final String label;
        private final int level;

        SkillRow(String label, int level)
        {
            this.label = label;
            this.level = level;
        }

        String getLabel()
        {
            return label;
        }

        int getLevel()
        {
            return level;
        }
    }

    static JournalSnapshot fromClient(
        net.runelite.api.Client client,
        boolean syncEnabled,
        boolean bankSyncEnabled,
        boolean publicProfileEnabled,
        PairingState pairing,
        JournalSyncService.SyncStatus syncStatus
    )
    {
        var player = client.getLocalPlayer();
        String rsn = player != null ? player.getName() : "Unknown";
        int cb = player != null ? player.getCombatLevel() : 0;
        int qp = client.getVarpValue(net.runelite.api.VarPlayer.QUEST_POINTS);
        int total = client.getTotalLevel();

        List<SkillRow> skills = new ArrayList<>();
        addSkill(skills, client, Skill.ATTACK);
        addSkill(skills, client, Skill.STRENGTH);
        addSkill(skills, client, Skill.DEFENCE);
        addSkill(skills, client, Skill.RANGED);
        addSkill(skills, client, Skill.MAGIC);
        addSkill(skills, client, Skill.PRAYER);
        addSkill(skills, client, Skill.HITPOINTS);
        addSkill(skills, client, Skill.SLAYER);

        int finished = 0;
        List<String> recent = new ArrayList<>();
        for (Quest quest : Quest.values())
        {
            QuestState state = quest.getState(client);
            if (state == QuestState.FINISHED)
            {
                finished++;
            }
            else if (state == QuestState.IN_PROGRESS && recent.size() < 6)
            {
                recent.add(quest.getName());
            }
        }

        String pairCode = pairing != null && pairing.needsPairingDisplay() ? pairing.getPairCode() : null;
        boolean linked = pairing != null && pairing.isLinked();
        boolean expired = pairing != null && pairing.isCodeExpired();
        String expiryLabel = pairing != null ? pairing.getExpiryLabel() : null;

        return new JournalSnapshot(
            rsn,
            cb,
            qp,
            total,
            finished,
            skills,
            recent,
            syncEnabled,
            bankSyncEnabled,
            publicProfileEnabled,
            pairCode,
            linked,
            expired,
            expiryLabel,
            syncStatus
        );
    }

    private static void addSkill(List<SkillRow> skills, net.runelite.api.Client client, Skill skill)
    {
        skills.add(new SkillRow(capitalize(skill.getName()), client.getRealSkillLevel(skill)));
    }

    private static String capitalize(String name)
    {
        if (name == null || name.isEmpty())
        {
            return name;
        }
        return Character.toUpperCase(name.charAt(0)) + name.substring(1).toLowerCase();
    }
}

package com.osrsjournal;

import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Syncs game data to the OSRS Journal cloud through Edge Functions,
 * authenticated by a per-character sync token.
 *
 * <p>Thin orchestration layer between the plugin's event handlers and
 * {@link HostedApiService}: it looks up the token for the RSN, shapes the
 * payload, and feeds pairing-state updates back to {@link PairingService}.
 * All methods perform network I/O and must be called from executor threads,
 * never the client thread.
 */
@Slf4j
@Singleton
class JournalSyncService
{
    @Inject
    private HostedApiService hostedApiService;

    @Inject
    private SyncTokenStore syncTokenStore;

    @Inject
    private PairingService pairingService;

    private final AtomicReference<SyncStatus> lastStatus = new AtomicReference<>(SyncStatus.idle());

    /** Ensures a sync token exists for {@code rsn}; may call pair-init. */
    PairingState ensurePairing(String rsn)
    {
        return pairingService.ensurePairing(rsn);
    }

    PairingState getPairingState(String rsn)
    {
        return pairingService.getCurrentState(rsn);
    }

    String getSyncToken(String rsn)
    {
        return syncTokenStore.getToken(rsn);
    }

    SyncStatus getLastStatus()
    {
        return lastStatus.get();
    }

    HostedApiService.SyncResult syncLogin(
        String rsn,
        List<Map<String, Object>> playerRecord,
        List<Map<String, Object>> skillRecords,
        List<Map<String, Object>> questRecords,
        List<Map<String, Object>> equipRecords,
        List<Map<String, Object>> diaryRecords,
        List<Map<String, Object>> combatAchievementRecords,
        List<Map<String, Object>> inventoryRecords
    )
    {
        // Note: profile_public is intentionally NOT sent here — the website's
        // privacy toggle is the source of truth once an account is linked.
        // It is only pushed from syncPrivacy() when the user changes the
        // RuneLite config toggle.
        HostedApiService.SyncPayload payload = new HostedApiService.SyncPayload()
            .players(playerRecord)
            .skills(skillRecords)
            .quests(questRecords)
            .diaries(diaryRecords)
            .combatAchievements(combatAchievementRecords)
            .touchLastSynced(true);

        // Null equipment means the container was not loaded yet — skip the
        // replace so we don't wipe a previous snapshot of worn gear.
        if (equipRecords != null)
        {
            payload.equipment(equipRecords, true);
        }
        if (inventoryRecords != null)
        {
            payload.inventory(inventoryRecords);
        }

        return syncWithRepair(rsn, payload, "login");
    }

    boolean syncSkills(String rsn, List<Map<String, Object>> records)
    {
        return syncPartial(rsn, new HostedApiService.SyncPayload().skills(records), "skills");
    }

    boolean syncQuests(String rsn, List<Map<String, Object>> records)
    {
        return syncPartial(rsn, new HostedApiService.SyncPayload().quests(records), "quests");
    }

    boolean syncDiariesAndCombatAchievements(
        String rsn,
        List<Map<String, Object>> diaryRecords,
        List<Map<String, Object>> combatAchievementRecords
    )
    {
        return syncPartial(
            rsn,
            new HostedApiService.SyncPayload()
                .diaries(diaryRecords)
                .combatAchievements(combatAchievementRecords),
            "diaries+CA"
        );
    }

    boolean syncEquipment(String rsn, List<Map<String, Object>> records)
    {
        return syncPartial(rsn, new HostedApiService.SyncPayload().equipment(records, true).touchLastSynced(false), "equipment");
    }

    boolean syncBank(String rsn, List<Map<String, Object>> records)
    {
        return syncPartial(rsn, new HostedApiService.SyncPayload().bank(records, true), "bank");
    }

    /** Inventory snapshot stored in player_inventory (counts with bank on the site). */
    boolean syncInventory(String rsn, List<Map<String, Object>> records)
    {
        return syncPartial(rsn, new HostedApiService.SyncPayload().inventory(records).touchLastSynced(false), "inventory");
    }

    /** Bank + inventory in one request so ownership data stays consistent. */
    boolean syncBankAndInventory(
        String rsn,
        List<Map<String, Object>> bankRecords,
        List<Map<String, Object>> inventoryRecords
    )
    {
        return syncPartial(
            rsn,
            new HostedApiService.SyncPayload().bankAndInventory(bankRecords, inventoryRecords),
            "bank+inventory"
        );
    }

    /**
     * Looting bag / POH costume-room snapshots. Each map is
     * {@code container} + {@code items} (list of item_id / item_name / quantity).
     */
    boolean syncStashes(String rsn, List<Map<String, Object>> pages)
    {
        if (pages == null || pages.isEmpty())
        {
            return true;
        }
        return syncPartial(
            rsn,
            new HostedApiService.SyncPayload().stashes(pages).touchLastSynced(false),
            "stashes"
        );
    }

    /**
     * Collection-log pages opened in-game. Each map is
     * {@code page} + {@code items} (list of item_id / item_name / quantity).
     */
    boolean syncCollectionLog(String rsn, List<Map<String, Object>> pages)
    {
        if (pages == null || pages.isEmpty())
        {
            return true;
        }
        return syncPartial(
            rsn,
            new HostedApiService.SyncPayload().collectionLogPages(pages),
            "collection log"
        );
    }

    /** Pushes the profile privacy flag; only called when the user flips the config toggle. */
    boolean syncPrivacy(String rsn, boolean isPublic)
    {
        return syncPartial(rsn, new HostedApiService.SyncPayload()
            .profilePublic(isPublic)
            .touchLastSynced(false), "privacy");
    }

    private boolean syncPartial(String rsn, HostedApiService.SyncPayload payload, String label)
    {
        return syncWithRepair(rsn, payload, label).isSuccess();
    }

    private HostedApiService.SyncResult syncWithRepair(
        String rsn,
        HostedApiService.SyncPayload payload,
        String label
    )
    {
        String token = syncTokenStore.getToken(rsn);
        if (token == null)
        {
            PairingState paired = pairingService.ensurePairing(rsn);
            token = paired != null ? paired.getSyncToken() : syncTokenStore.getToken(rsn);
            if (token == null)
            {
                lastStatus.set(SyncStatus.error("No sync token — open the sidebar to pair."));
                log.warn("No sync token for '{}' — {} sync skipped", rsn, label);
                return HostedApiService.SyncResult.failed(true, "No sync token");
            }
        }

        HostedApiService.SyncResult result = hostedApiService.sync(rsn, token, payload);
        if (!result.isSuccess() && result.isAuthFailed())
        {
            log.info("OSRS Journal: sync token stale for '{}' during {}, re-pairing", rsn, label);
            pairingService.ensurePairing(rsn);
            token = syncTokenStore.getToken(rsn);
            if (token != null)
            {
                result = hostedApiService.sync(rsn, token, payload);
            }
        }

        if (result.isSuccess())
        {
            pairingService.updateLinkedState(rsn, syncTokenStore.getToken(rsn), result.isClaimed());
            if (result.hasWarnings())
            {
                String warn = String.join("; ", result.getWarnings());
                lastStatus.set(SyncStatus.warning(label + ": " + warn));
            }
            else
            {
                lastStatus.set(SyncStatus.ok(label));
            }
        }
        else
        {
            String err = result.getError() != null ? result.getError() : (label + " sync failed");
            lastStatus.set(SyncStatus.error(err));
            log.warn("OSRS Journal: {} sync failed for '{}': {}", label, rsn, err);
        }
        return result;
    }

    /** Compact status shown in the sidebar. */
    static final class SyncStatus
    {
        enum Kind { IDLE, OK, WARNING, ERROR }

        private final Kind kind;
        private final String message;
        private final long atMs;

        private SyncStatus(Kind kind, String message)
        {
            this.kind = kind;
            this.message = message;
            this.atMs = System.currentTimeMillis();
        }

        static SyncStatus idle()
        {
            return new SyncStatus(Kind.IDLE, null);
        }

        static SyncStatus ok(String label)
        {
            return new SyncStatus(Kind.OK, "Last sync OK (" + label + ")");
        }

        static SyncStatus warning(String message)
        {
            return new SyncStatus(Kind.WARNING, message);
        }

        static SyncStatus error(String message)
        {
            return new SyncStatus(Kind.ERROR, message);
        }

        Kind getKind()
        {
            return kind;
        }

        String getMessage()
        {
            return message;
        }

        long getAtMs()
        {
            return atMs;
        }

        /** Relative age for sidebar, e.g. "just now", "2m ago". */
        String getAgeLabel()
        {
            if (kind == Kind.IDLE)
            {
                return null;
            }
            long secs = Math.max(0, (System.currentTimeMillis() - atMs) / 1000L);
            if (secs < 15)
            {
                return "just now";
            }
            if (secs < 60)
            {
                return secs + "s ago";
            }
            long mins = secs / 60;
            if (mins < 60)
            {
                return mins + "m ago";
            }
            return (mins / 60) + "h ago";
        }
    }
}

package com.osrsjournal;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

/**
 * Plugin settings. Plugin Hub requires any third-party network feature to be
 * <b>opt-in</b> (disabled by default) with the standard {@code warning} text.
 * Bank &amp; inventory sync is a second opt-in on top of Enable Sync.
 * The Advanced section only matters for self-hosted backends and stays collapsed.
 */
@ConfigGroup("osrsjournal")
public interface OsrsJournalConfig extends Config
{
    @ConfigSection(
        name = "Sync Options",
        description = "Control what data is synced and when. Enable Sync must be on before anything is sent.",
        position = 0
    )
    String syncSection = "sync";

    @ConfigItem(
        keyName = "syncEnabled",
        name = "Enable Sync",
        description = "Master switch. When on, syncs skills, quests, worn gear, diaries, combat "
            + "achievements, and Collection Log pages (when you open them in-game) to "
            + "journal.osrsjournal.com while you play. Off by default — enable this, "
            + "confirm the warning, then enter the pairing code from the sidebar on the website. "
            + "Bank & Inventory is a separate toggle below and does nothing while this is off.",
        // Exact wording required by RuneLite Plugin Hub / example-plugin AGENTS.md
        warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers",
        section = syncSection,
        position = 1
    )
    default boolean syncEnabled()
    {
        // Plugin Hub: third-party server features must be disabled by default.
        return false;
    }

    @ConfigItem(
        keyName = "syncBank",
        name = "Sync Bank & Inventory",
        description = "Requires Enable Sync. When on, uploads your full bank whenever you open it, "
            + "keeps your inventory snapshot updated, and records looting-bag (Check) and Player-Owned "
            + "House costume-room storage when you open them so items count wherever they sit "
            + "(gear planner, Graceful marks, wealth, etc.). Only you can see this when signed in — "
            + "public profiles never include bank, inventory, looting bag, or house storage.",
        warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers",
        section = syncSection,
        position = 2
    )
    default boolean syncBank()
    {
        return false;
    }

    @ConfigItem(
        keyName = "publicProfile",
        name = "Public Profile",
        description = "When linked, skills and quests are visible to others on journal.osrsjournal.com "
            + "(like Wise Old Man). Bank, inventory, looting bag, house storage, and worn gear "
            + "stay private either way. "
            + "Requires Enable Sync for the plugin to push this setting.",
        section = syncSection,
        position = 3
    )
    default boolean publicProfile()
    {
        return true;
    }

    @ConfigItem(
        keyName = "skillDebounceSeconds",
        name = "Skill Debounce (s)",
        description = "Seconds to wait after the last XP gain before syncing skills (avoids spam while training).",
        section = syncSection,
        position = 4
    )
    @Range(min = 1, max = 60)
    default int skillDebounceSeconds()
    {
        return 8;
    }

    @ConfigSection(
        name = "Advanced",
        description = "Self-hosted deployments only — leave blank for journal.osrsjournal.com. "
            + "Only point API override at a server you trust.",
        position = 5,
        closedByDefault = true
    )
    String advancedSection = "advanced";

    @ConfigItem(
        keyName = "apiBaseUrl",
        name = "API override",
        description = "Leave blank to use the built-in OSRS Journal cloud. Self-hosters only — "
            + "must be a trusted HTTPS Edge Functions base URL.",
        section = advancedSection,
        position = 6
    )
    default String apiBaseUrl()
    {
        return "";
    }

    @ConfigItem(
        keyName = "pluginClientId",
        name = "Client ID",
        description = "X-Plugin-Client-Id override for self-hosted backends. Leave blank to use the built-in id.",
        section = advancedSection,
        position = 7
    )
    default String pluginClientId()
    {
        return "";
    }
}

package com.osrsjournal;

import java.awt.BorderLayout;
import java.awt.GridLayout;
import java.awt.event.ActionEvent;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JEditorPane;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Sidebar panel: character summary, pairing call-to-action, and buttons to open
 * the full web journal or refresh.
 *
 * <p>Renders from {@link JournalSnapshot} view-models only — all game-state reads
 * happen on the client thread before a snapshot reaches this class, and all
 * methods here are EDT-only except where noted. The body is a single HTML
 * {@link JEditorPane} because the layout (pair code, skill table, quest list)
 * is easier to keep readable as markup than as nested Swing containers.
 */
class OsrsJournalPanel extends PluginPanel
{
    private final JEditorPane summaryPane = new JEditorPane();
    private final JLabel statusLabel = new JLabel("Log in to view your journal.");
    private final JournalBrowser journalBrowser;
    private final ScheduledExecutorService executor;
    private JButton openFullButton;
    private JButton newCodeButton;
    private JButton refreshButton;
    private JournalSnapshot lastSnapshot;
    private Timer countdownTimer;

    @Inject
    OsrsJournalPanel(JournalBrowser journalBrowser, ScheduledExecutorService executor)
    {
        super();
        this.journalBrowser = journalBrowser;
        this.executor = executor;
    }

    void init()
    {
        setLayout(new BorderLayout(0, 8));
        setBorder(new EmptyBorder(10, 10, 10, 10));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JLabel heading = new JLabel("OSRS Journal");
        heading.setFont(FontManager.getRunescapeSmallFont());
        heading.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

        statusLabel.setFont(FontManager.getRunescapeSmallFont());
        statusLabel.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);

        summaryPane.setEditable(false);
        summaryPane.setContentType("text/html");
        summaryPane.addHyperlinkListener(e ->
        {
            if (e.getEventType() == javax.swing.event.HyperlinkEvent.EventType.ACTIVATED && e.getURL() != null)
            {
                net.runelite.client.util.LinkBrowser.browse(e.getURL().toString());
            }
        });
        summaryPane.putClientProperty(JEditorPane.HONOR_DISPLAY_PROPERTIES, Boolean.TRUE);
        summaryPane.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        summaryPane.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));
        summaryPane.setText(buildHtml(null));

        openFullButton = new JButton("Open full journal");
        openFullButton.addActionListener(this::openFullJournal);

        newCodeButton = new JButton("New code");
        newCodeButton.setToolTipText("Request a fresh pairing code from the server");
        newCodeButton.addActionListener(e -> requestNewCode());
        newCodeButton.setVisible(false);

        refreshButton = new JButton("Refresh");
        refreshButton.addActionListener(e -> requestRefresh());

        JPanel buttons = new JPanel(new GridLayout(0, 1, 0, 6));
        buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);
        buttons.add(openFullButton);
        buttons.add(newCodeButton);
        buttons.add(refreshButton);

        JPanel north = new JPanel(new BorderLayout(0, 6));
        north.setBackground(ColorScheme.DARK_GRAY_COLOR);
        north.add(heading, BorderLayout.NORTH);
        north.add(statusLabel, BorderLayout.SOUTH);

        add(north, BorderLayout.NORTH);
        add(summaryPane, BorderLayout.CENTER);
        add(buttons, BorderLayout.SOUTH);

        // Keep pairing countdown / sync "Xm ago" labels fresh without a full client read.
        countdownTimer = new Timer(15_000, e ->
        {
            if (lastSnapshot != null && tickListener != null)
            {
                tickListener.run();
            }
        });
        countdownTimer.setRepeats(true);
        countdownTimer.start();
    }

    void disposeTimers()
    {
        if (countdownTimer != null)
        {
            countdownTimer.stop();
            countdownTimer = null;
        }
    }

    void updateSummary(JournalSnapshot snapshot)
    {
        lastSnapshot = snapshot;
        if (snapshot == null)
        {
            statusLabel.setText("Log in to view your journal.");
            summaryPane.setText(buildHtml(null));
            newCodeButton.setVisible(false);
            return;
        }

        statusLabel.setText(snapshot.getStatusText());
        summaryPane.setText(buildHtml(snapshot));
        boolean showNewCode = snapshot.isSyncEnabled()
            && !snapshot.isAccountLinked()
            && (snapshot.getPairCode() != null || snapshot.isPairCodeExpired());
        newCodeButton.setVisible(showNewCode);
        newCodeButton.setText(snapshot.isPairCodeExpired() ? "New code (expired)" : "New code");
    }

    private String currentRsn;

    void setCurrentRsn(String rsn)
    {
        this.currentRsn = rsn;
    }

    private void openFullJournal(ActionEvent e)
    {
        final String rsn = currentRsn;
        openFullButton.setEnabled(false);
        statusLabel.setText("Opening journal...");
        executor.execute(() ->
        {
            String status = journalBrowser.openInBrowser(rsn);
            SwingUtilities.invokeLater(() ->
            {
                openFullButton.setEnabled(true);
                statusLabel.setText(status);
            });
        });
    }

    private void requestRefresh()
    {
        if (refreshListener != null)
        {
            refreshListener.run();
        }
    }

    private void requestNewCode()
    {
        if (newCodeListener != null)
        {
            newCodeButton.setEnabled(false);
            statusLabel.setText("Requesting a new pairing code...");
            newCodeListener.run();
        }
    }

    /** Called after a New code request finishes (success or fail). */
    void onNewCodeFinished(boolean ok)
    {
        newCodeButton.setEnabled(true);
        if (!ok)
        {
            statusLabel.setText("Couldn't get a new code — try again in a moment.");
        }
    }

    private Runnable refreshListener;
    private Runnable newCodeListener;
    private Runnable tickListener;

    void setRefreshListener(Runnable refreshListener)
    {
        this.refreshListener = refreshListener;
    }

    void setNewCodeListener(Runnable newCodeListener)
    {
        this.newCodeListener = newCodeListener;
    }

    /** Lightweight redraw (pairing countdown / sync age). */
    void setTickListener(Runnable tickListener)
    {
        this.tickListener = tickListener;
    }

    private static String buildHtml(JournalSnapshot s)
    {
        if (s == null)
        {
            return htmlWrap(
                "<p style='color:#94a3b8'>Your stats, quests, and sync status appear here while logged in.</p>"
                    + "<p style='color:#64748b'>Use <b>Open full journal</b> for the complete planner UI in your browser.</p>"
            );
        }

        StringBuilder sb = new StringBuilder();
        sb.append("<p style='color:#f1f5f9;font-size:13px'><b>").append(escape(s.getRsn())).append("</b></p>");
        sb.append("<p style='color:#94a3b8'>Combat ").append(s.getCombatLevel())
            .append(" · QP ").append(s.getQuestPoints())
            .append(" · Total ").append(s.getTotalLevel()).append("</p>");

        // Opt-in checklist
        sb.append("<p style='color:#64748b;font-size:11px;margin-top:6px'>")
            .append(optLine("Enable Sync", s.isSyncEnabled(), true))
            .append("<br/>")
            .append(optLine("Bank &amp; Inventory", s.isBankSyncEnabled(), s.isSyncEnabled()))
            .append("<br/>")
            .append(optLine("Public profile", s.isPublicProfileEnabled(), s.isSyncEnabled()))
            .append("</p>");

        if (s.isBankSyncIneffective())
        {
            sb.append("<p style='color:#fbbf24;font-size:11px'>Bank &amp; Inventory is on, but <b>Enable Sync</b> "
                + "is off — nothing is uploaded until you enable Sync.</p>");
        }

        if (!s.isSyncEnabled())
        {
            sb.append("<hr/>");
            sb.append("<p style='color:#fbbf24;font-size:11px'>Sync is off. Enable <b>Enable Sync</b> in plugin "
                + "settings (you'll see a confirmation about a 3rd-party server), then pair on the website.</p>");
            sb.append("<p style='color:#64748b;font-size:11px'><a href='")
                .append(JournalConstants.PRIVACY_URL)
                .append("' style='color:#60a5fa'>Privacy policy</a></p>");
        }
        else if (s.getPairCode() != null && !s.getPairCode().isEmpty() && !s.isAccountLinked())
        {
            sb.append("<hr/>");
            sb.append("<p style='color:#94a3b8;margin-bottom:4px'><b>Link account</b></p>");
            if (s.isPairCodeExpired())
            {
                sb.append("<p style='color:#f87171;font-size:12px'><b>Code expired</b> — click <b>New code</b> below.</p>");
                sb.append("<p style='color:#64748b;font-size:11px'>Old code: <span style='letter-spacing:1px'>")
                    .append(escape(s.getPairCode())).append("</span></p>");
            }
            else
            {
                sb.append("<p style='color:#f1f5f9;font-size:18px;letter-spacing:2px'><b>")
                    .append(escape(s.getPairCode())).append("</b></p>");
                if (s.getPairExpiryLabel() != null)
                {
                    sb.append("<p style='color:#fbbf24;font-size:11px'>")
                        .append(escape(s.getPairExpiryLabel())).append("</p>");
                }
            }
            sb.append("<p style='color:#64748b;font-size:11px'>1. Sign in at "
                + "<a href='" + JournalConstants.WEB_APP_URL + "' style='color:#60a5fa'>journal.osrsjournal.com</a><br/>"
                + "2. Enter this code under <b>Link character</b></p>");
        }
        else if (s.isAccountLinked())
        {
            sb.append("<p style='color:#22c55e;font-size:11px'>✓ Account linked.</p>");
        }

        if (s.isSyncEnabled() && s.getSyncStatus() != null
            && s.getSyncStatus().getKind() != JournalSyncService.SyncStatus.Kind.IDLE)
        {
            JournalSyncService.SyncStatus st = s.getSyncStatus();
            String color = st.getKind() == JournalSyncService.SyncStatus.Kind.ERROR ? "#f87171"
                : st.getKind() == JournalSyncService.SyncStatus.Kind.WARNING ? "#fbbf24" : "#94a3b8";
            sb.append("<p style='color:").append(color).append(";font-size:11px'>");
            if (st.getKind() == JournalSyncService.SyncStatus.Kind.ERROR)
            {
                sb.append("<b>Sync failed:</b> ");
            }
            else if (st.getKind() == JournalSyncService.SyncStatus.Kind.WARNING)
            {
                sb.append("<b>Partial sync:</b> ");
            }
            if (st.getMessage() != null)
            {
                sb.append(escape(st.getMessage()));
            }
            if (st.getAgeLabel() != null)
            {
                sb.append(" <span style='color:#64748b'>(").append(escape(st.getAgeLabel())).append(")</span>");
            }
            if (st.getKind() == JournalSyncService.SyncStatus.Kind.ERROR)
            {
                sb.append(" — click Refresh or re-open the bank to retry.");
            }
            sb.append("</p>");
        }

        if (s.isSyncEnabled())
        {
            sb.append("<p style='color:#64748b;font-size:11px'>")
                .append("<a href='").append(JournalConstants.PRIVACY_URL)
                .append("' style='color:#60a5fa'>Privacy</a>")
                .append(" · Open full journal uses a short-lived live session when synced.")
                .append("</p>");
        }

        sb.append("<hr/>");
        sb.append("<p style='color:#94a3b8;margin-bottom:4px'><b>Skills</b></p>");
        sb.append("<table width='100%' cellpadding='2' cellspacing='0'>");
        for (JournalSnapshot.SkillRow row : s.getSkills())
        {
            sb.append("<tr><td style='color:#cbd5e1'>").append(escape(row.getLabel()))
                .append("</td><td align='right' style='color:#f1f5f9'>")
                .append(row.getLevel()).append("</td></tr>");
        }
        sb.append("</table>");
        sb.append("<hr/>");
        sb.append("<p style='color:#94a3b8'>Quests finished: <span style='color:#f1f5f9'>")
            .append(s.getQuestsFinished()).append("</span></p>");
        if (!s.getRecentQuests().isEmpty())
        {
            sb.append("<p style='color:#64748b;margin-bottom:4px'>In progress / recent:</p><ul style='margin-top:0;padding-left:16px'>");
            for (String quest : s.getRecentQuests())
            {
                sb.append("<li style='color:#cbd5e1;font-size:11px'>").append(escape(quest)).append("</li>");
            }
            sb.append("</ul>");
        }
        sb.append("<p style='color:#64748b;font-size:11px'>Diaries, combat achievements, gear, collection log "
            + "(open pages in-game to sync), and export live in the browser journal.</p>");
        return htmlWrap(sb.toString());
    }

    private static String optLine(String label, boolean on, boolean effective)
    {
        if (!effective && on)
        {
            return "<span style='color:#fbbf24'>● " + label + " (needs Enable Sync)</span>";
        }
        if (on)
        {
            return "<span style='color:#22c55e'>● " + label + " on</span>";
        }
        return "<span style='color:#64748b'>○ " + label + " off</span>";
    }

    private static String htmlWrap(String body)
    {
        return "<html><body style='font-family:sans-serif;background:#171b26;margin:0;padding:0'>"
            + body + "</body></html>";
    }

    private static String escape(String text)
    {
        return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }
}

package com.osrsjournal;

