    /**
     * {@code null} when the equipment container has not loaded yet — callers
     * must not treat that as "player is naked" and replace cloud gear.
     */
    private List<Map<String, Object>> buildEquipmentRecords(String rsn)
    {
        ItemContainer container = client.getItemContainer(InventoryID.EQUIPMENT);
        if (container == null)
        {
            return null;
        }

        List<Map<String, Object>> records = new ArrayList<>();
        Item[] items = container.getItems();

        for (EquipmentInventorySlot slot : EquipmentInventorySlot.values())
        {
            int idx = slot.getSlotIdx();
            if (idx < 0 || idx >= items.length)
            {
                continue;
            }

            Item item = items[idx];
            if (item == null || item.getId() == -1)
            {
                continue;
            }

            int itemId = itemManager.canonicalize(item.getId());
            String itemName = resolveItemName(itemId);
            records.add(ImmutableMap.<String, Object>builder()
                .put("rsn", rsn)
                .put("slot_id", idx)
                .put("slot_name", canonicalSlotName(slot))
                .put("item_id", itemId)
                .put("item_name", itemName)
                .put("quantity", item.getQuantity())
                .build());
        }

        return records;
    }

    /**
     * Website {@code SLOT_ORDER} uses {@code neck}; RuneLite's enum is {@code AMULET}.
     */
    static String canonicalSlotName(EquipmentInventorySlot slot)
    {
        if (slot == EquipmentInventorySlot.AMULET)
        {
            return "neck";
        }
        return slot.name().toLowerCase();
    }

    private List<Map<String, Object>> buildBankRecords(String rsn)
    {
        ItemContainer container = client.getItemContainer(InventoryID.BANK);
        if (container == null)
        {
            return new ArrayList<>();
        }
        List<Map<String, Object>> records = new ArrayList<>();
        for (Map<String, Object> row : buildItemRecords(container))
        {
            records.add(ImmutableMap.of(
                "rsn", rsn,
                "item_id", row.get("item_id"),
                "item_name", row.get("item_name"),
                "quantity", row.get("quantity")
            ));
        }
        return records;
    }

    /** Full inventory snapshot (canonicalized), same shape as bank rows minus rsn. */
    private List<Map<String, Object>> buildInventoryRecords()
    {
        ItemContainer container = client.getItemContainer(InventoryID.INVENTORY);
        if (container == null)
        {
            return new ArrayList<>();
        }
        return buildItemRecords(container);
    }

    /**
     * Snapshots of extra storage currently loaded in the client. Unloaded
     * containers are omitted so a previous cloud snapshot is not wiped.
     */
    private List<Map<String, Object>> buildLoadedStashPages()
    {
        List<Map<String, Object>> pages = new ArrayList<>();
        for (int containerId : ExtraItemStorage.containerIds())
        {
            ItemContainer container = client.getItemContainer(containerId);
            if (container == null)
            {
                continue;
            }
            pages.add(ImmutableMap.of(
                "container", ExtraItemStorage.keyFor(containerId),
                "items", buildItemRecords(container)
            ));
        }
        return pages;
    }

    /** Canonicalized, merged stacks from any item container. */
    private List<Map<String, Object>> buildItemRecords(ItemContainer container)
    {
        Map<Integer, int[]> qtyById = new java.util.LinkedHashMap<>();
        Map<Integer, String> nameById = new HashMap<>();
        for (Item item : container.getItems())
        {
            if (item == null || item.getId() == -1 || item.getQuantity() <= 0)
            {
                continue;
            }
            int itemId = itemManager.canonicalize(item.getId());
            int[] qty = qtyById.get(itemId);
            if (qty == null)
            {
                qtyById.put(itemId, new int[]{item.getQuantity()});
                nameById.put(itemId, resolveItemName(itemId));
            }
            else
            {
                qty[0] += item.getQuantity();
            }
        }

        List<Map<String, Object>> records = new ArrayList<>(qtyById.size());
        for (Map.Entry<Integer, int[]> e : qtyById.entrySet())
        {
            records.add(ImmutableMap.of(
                "item_id",   e.getKey(),
                "item_name", nameById.get(e.getKey()),
                "quantity",  e.getValue()[0]
            ));
        }
        return records;
    }

    // ── Utilities ─────────────────────────────────────────────────────────────

    /**
     * Resolves an item ID to its display name via the client's item composition cache.
     * Returns "Unknown" rather than null if the composition is unavailable.
     */
    private String resolveItemName(int itemId)
    {
        ItemComposition comp = itemManager.getItemComposition(itemId);
        if (comp == null)
        {
            return "Unknown";
        }
        String name = comp.getName();
        return (name == null || name.equals("null")) ? "Unknown" : name;
    }

    /** Computes total XP across all skills (OVERALL not included in Skill.values() sum). */
    private long computeTotalXp()
    {
        long total = 0;
        for (Skill skill : Skill.values())
        {
            if (skill != Skill.OVERALL)
            {
                total += client.getSkillExperience(skill);
            }
        }
        return total;
    }

    private void cancelSkillDebounce()
    {
        if (skillSyncFuture != null && !skillSyncFuture.isDone())
        {
            skillSyncFuture.cancel(false);
            skillSyncFuture = null;
        }
    }

    private void cancelEquipmentDebounce()
    {
        if (equipmentSyncFuture != null && !equipmentSyncFuture.isDone())
        {
            equipmentSyncFuture.cancel(false);
            equipmentSyncFuture = null;
        }
    }

    private void cancelInventoryDebounce()
    {
        if (inventorySyncFuture != null && !inventorySyncFuture.isDone())
        {
            inventorySyncFuture.cancel(false);
            inventorySyncFuture = null;
        }
    }

    private void cancelProgressDebounce()
    {
        if (progressSyncFuture != null && !progressSyncFuture.isDone())
        {
            progressSyncFuture.cancel(false);
            progressSyncFuture = null;
        }
    }

    private void cancelCollectionLogDebounce()
    {
        if (collectionLogSyncFuture != null && !collectionLogSyncFuture.isDone())
        {
            collectionLogSyncFuture.cancel(false);
            collectionLogSyncFuture = null;
        }
    }

    private void cancelStashDebounce()
    {
        for (ScheduledFuture<?> future : stashSyncFutures.values())
        {
            if (future != null && !future.isDone())
            {
                future.cancel(false);
            }
        }
        stashSyncFutures.clear();
        pendingStashRecords.clear();
    }

    /**
     * Sidebar Refresh button: retries pairing if there's no code yet (e.g. the
     * backend was unreachable at login), then redraws the panel.
     */
    private void manualRefresh()
    {
        final String rsn = currentRsn;
        if (rsn == null || !config.syncEnabled())
        {
            // Local sidebar only — no pair-init / HTTP unless sync is opted in.
            refreshPanel();
            return;
        }
        executor.execute(() ->
        {
            // pair-init is idempotent: reuses the sync token and reports the
            // server-side linked state, issuing a fresh code if unclaimed.
            // Also refresh when the local code countdown has expired.
            PairingState state = journalSyncService.getPairingState(rsn);
            if (state == null || !state.isLinked() || state.isCodeExpired())
            {
                journalSyncService.ensurePairing(rsn);
            }
            refreshPanel();
        });
    }

    /** Sidebar "New code" — always hits pair-init for a fresh code. */
    private void requestNewPairingCode()
    {
        final String rsn = currentRsn;
        if (rsn == null || !config.syncEnabled())
        {
            if (panel != null)
            {
                SwingUtilities.invokeLater(() -> panel.onNewCodeFinished(false));
            }
            return;
        }
        executor.execute(() ->
        {
            PairingState state = journalSyncService.ensurePairing(rsn);
            boolean ok = state != null && state.needsPairingDisplay();
            refreshPanel();
            if (panel != null)
            {
                SwingUtilities.invokeLater(() -> panel.onNewCodeFinished(ok || (state != null && state.isLinked())));
            }
        });
    }

    /** Reads live client data on the client thread, then updates the sidebar on the EDT. */
    private void refreshPanel()
    {
        if (panel == null)
        {
            return;
        }

        clientThread.invokeLater(() ->
        {
            JournalSnapshot snapshot = null;
            if (client.getGameState() == GameState.LOGGED_IN)
            {
                String rsn = client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : null;
                PairingState pairing = rsn != null ? journalSyncService.getPairingState(rsn) : null;
                snapshot = JournalSnapshot.fromClient(
                    client,
                    config.syncEnabled(),
                    config.syncBank(),
                    config.publicProfile(),
                    pairing,
                    journalSyncService.getLastStatus()
                );
            }
            final JournalSnapshot captured = snapshot;
            final String panelRsn = snapshot != null ? snapshot.getRsn() : null;
            SwingUtilities.invokeLater(() ->
            {
                panel.setCurrentRsn(panelRsn);
                panel.updateSummary(captured);
            });
        });
    }

    private static String nowIso()
    {
        return java.time.Instant.now().toString();
    }

    private static Set<Integer> buildTrackedProgressVarbits()
    {
        Set<Integer> ids = new HashSet<>();
        int[] diary = {
            Varbits.DIARY_ARDOUGNE_EASY, Varbits.DIARY_ARDOUGNE_MEDIUM, Varbits.DIARY_ARDOUGNE_HARD, Varbits.DIARY_ARDOUGNE_ELITE,
            Varbits.DIARY_DESERT_EASY, Varbits.DIARY_DESERT_MEDIUM, Varbits.DIARY_DESERT_HARD, Varbits.DIARY_DESERT_ELITE,
            Varbits.DIARY_FALADOR_EASY, Varbits.DIARY_FALADOR_MEDIUM, Varbits.DIARY_FALADOR_HARD, Varbits.DIARY_FALADOR_ELITE,
            Varbits.DIARY_FREMENNIK_EASY, Varbits.DIARY_FREMENNIK_MEDIUM, Varbits.DIARY_FREMENNIK_HARD, Varbits.DIARY_FREMENNIK_ELITE,
            Varbits.DIARY_KANDARIN_EASY, Varbits.DIARY_KANDARIN_MEDIUM, Varbits.DIARY_KANDARIN_HARD, Varbits.DIARY_KANDARIN_ELITE,
            Varbits.DIARY_KARAMJA_EASY, Varbits.DIARY_KARAMJA_MEDIUM, Varbits.DIARY_KARAMJA_HARD, Varbits.DIARY_KARAMJA_ELITE,
            Varbits.DIARY_KOUREND_EASY, Varbits.DIARY_KOUREND_MEDIUM, Varbits.DIARY_KOUREND_HARD, Varbits.DIARY_KOUREND_ELITE,
            Varbits.DIARY_LUMBRIDGE_EASY, Varbits.DIARY_LUMBRIDGE_MEDIUM, Varbits.DIARY_LUMBRIDGE_HARD, Varbits.DIARY_LUMBRIDGE_ELITE,
            Varbits.DIARY_MORYTANIA_EASY, Varbits.DIARY_MORYTANIA_MEDIUM, Varbits.DIARY_MORYTANIA_HARD, Varbits.DIARY_MORYTANIA_ELITE,
            Varbits.DIARY_VARROCK_EASY, Varbits.DIARY_VARROCK_MEDIUM, Varbits.DIARY_VARROCK_HARD, Varbits.DIARY_VARROCK_ELITE,
            Varbits.DIARY_WESTERN_EASY, Varbits.DIARY_WESTERN_MEDIUM, Varbits.DIARY_WESTERN_HARD, Varbits.DIARY_WESTERN_ELITE,
            Varbits.DIARY_WILDERNESS_EASY, Varbits.DIARY_WILDERNESS_MEDIUM, Varbits.DIARY_WILDERNESS_HARD, Varbits.DIARY_WILDERNESS_ELITE,
        };
        for (int id : diary)
        {
            ids.add(id);
        }
        ids.add(Varbits.COMBAT_ACHIEVEMENT_TIER_EASY);
        ids.add(Varbits.COMBAT_ACHIEVEMENT_TIER_MEDIUM);
        ids.add(Varbits.COMBAT_ACHIEVEMENT_TIER_HARD);
        ids.add(Varbits.COMBAT_ACHIEVEMENT_TIER_ELITE);
        ids.add(Varbits.COMBAT_ACHIEVEMENT_TIER_MASTER);
        ids.add(Varbits.COMBAT_ACHIEVEMENT_TIER_GRANDMASTER);
        return Collections.unmodifiableSet(ids);
    }
}

package com.osrsjournal;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Tracks the pairing lifecycle between this RuneLite client and a website account.
 *
 * <p>Ownership of an RSN is proven by the plugin running while logged in as that
 * character: {@code pair-init} issues a short-lived code + sync token, the user
 * enters the code on the website, and {@code pair-claim} binds the token to their
 * account. To keep server load low, pair-init is only called when there is no
 * stored token (or the token went stale) — for already-linked characters the
 * linked state is derived from the {@code claimed} field of sync responses via
 * {@link #updateLinkedState}.
 *
 * <p>{@code lastState} is volatile: it is written from executor threads and read
 * from the client thread when building panel snapshots.
 */
@Slf4j
@Singleton
class PairingService
{
    @Inject
    private HostedApiService hostedApiService;

    @Inject
    private SyncTokenStore syncTokenStore;

    private volatile PairingState lastState;

    /**
     * Calls pair-init and stores the returned sync token. Network I/O — executor
     * threads only. Idempotent: for a known RSN the server reuses the existing
     * token and reports whether it is already linked; otherwise it mints a new
     * token and a fresh pairing code.
     */
    PairingState ensurePairing(String rsn)
    {
        PairingState init = hostedApiService.pairInit(rsn);
        if (init == null)
        {
            log.warn("Failed to initialize pairing for '{}'", rsn);
            return null;
        }

        syncTokenStore.saveToken(rsn, init.getSyncToken());
        lastState = init;
        log.debug("OSRS Journal: pairing code for '{}' is {} (linked={})",
            rsn, init.getPairCode(), init.isLinked());
        return init;
    }

    PairingState getCurrentState(String rsn)
    {
        if (lastState != null && rsn.equals(lastState.getRsn()))
        {
            return lastState;
        }
        // No live state from pair-init this session — having a stored token
        // doesn't prove the account was claimed on the website, so report
        // nothing rather than a false "linked".
        return null;
    }

    /**
     * Updates the linked state from a sync response ({@code claimed} field) —
     * lets the sidebar show "Account linked" without a pair-init round trip.
     * Never downgrades a state that is currently showing a pairing code.
     */
    void updateLinkedState(String rsn, String syncToken, boolean linked)
    {
        if (linked)
        {
            lastState = new PairingState(rsn, null, syncToken, true, 0);
        }
    }

    void clearState()
    {
        lastState = null;
    }
}

package com.osrsjournal;

import lombok.Getter;

/**
 * Immutable snapshot of a character's pairing status, shown in the sidebar.
 *
 * <p>Two shapes exist:
 * <ul>
 *   <li><b>Awaiting link</b> — {@code pairCode} set, {@code linked=false}: the user
 *       must enter the code on the website within {@code expiresInSeconds}.</li>
 *   <li><b>Linked</b> — {@code linked=true}, {@code pairCode} may be null when the
 *       state was derived from a sync response rather than pair-init.</li>
 * </ul>
 */
@Getter
class PairingState
{
    private final String rsn;
    private final String pairCode;
    private final String syncToken;
    private final boolean linked;
    private final int expiresInSeconds;
    /** Wall-clock millis when this state was created (for live countdown). */
    private final long issuedAtMs;

    PairingState(String rsn, String pairCode, String syncToken, boolean linked, int expiresInSeconds)
    {
        this(rsn, pairCode, syncToken, linked, expiresInSeconds, System.currentTimeMillis());
    }

    PairingState(
        String rsn,
        String pairCode,
        String syncToken,
        boolean linked,
        int expiresInSeconds,
        long issuedAtMs
    )
    {
        this.rsn = rsn;
        this.pairCode = pairCode;
        this.syncToken = syncToken;
        this.linked = linked;
        this.expiresInSeconds = expiresInSeconds;
        this.issuedAtMs = issuedAtMs;
    }

    boolean needsPairingDisplay()
    {
        return !linked && pairCode != null && !pairCode.isEmpty();
    }

    /** Seconds left before the pairing code expires; 0 if linked / no code / expired. */
    int getSecondsRemaining()
    {
        if (!needsPairingDisplay() || expiresInSeconds <= 0)
        {
            return 0;
        }
        long elapsed = (System.currentTimeMillis() - issuedAtMs) / 1000L;
        long left = expiresInSeconds - elapsed;
        return left > 0 ? (int) left : 0;
    }

    boolean isCodeExpired()
    {
        return needsPairingDisplay() && getSecondsRemaining() <= 0;
    }

    /** Human-readable countdown, e.g. "9:42" or "expired". */
    String getExpiryLabel()
    {
        if (!needsPairingDisplay())
        {
            return null;
        }
        int left = getSecondsRemaining();
        if (left <= 0)
        {
            return "expired — click New code";
        }
        int mins = left / 60;
        int secs = left % 60;
        return String.format("%d:%02d left", mins, secs);
    }
}

package com.osrsjournal;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

/**
 * Persists per-character sync tokens in RuneLite's config store.
 *
 * <p>The sync token is the plugin's <em>write credential</em>: the backend accepts
 * game data for an RSN only when the request carries that character's token
 * ({@code X-Sync-Token} header). Tokens are issued by {@code pair-init} and bound
 * to the RSN server-side, so a leaked token can only affect its own character —
 * and the plugin self-heals by re-pairing if the server rotates it.
 *
 * <p>Stored as a single JSON map ({@code rsn -> token}) under one config key so
 * users with multiple characters on the same RuneLite profile each keep their
 * own token across restarts.
 */
@Singleton
class SyncTokenStore
{
    private static final Type MAP_TYPE = new TypeToken<Map<String, String>>() {}.getType();

    @Inject
    private ConfigManager configManager;

    @Inject
    private Gson gson;

    String getToken(String rsn)
    {
        Map<String, String> tokens = load();
        return tokens.get(rsn);
    }

    void saveToken(String rsn, String syncToken)
    {
        Map<String, String> tokens = load();
        tokens.put(rsn, syncToken);
        persist(tokens);
    }

    private Map<String, String> load()
    {
        String json = configManager.getConfiguration("osrsjournal", "syncTokensJson");
        if (json == null || json.isEmpty())
        {
            return new HashMap<>();
        }
        Map<String, String> parsed = gson.fromJson(json, MAP_TYPE);
        return parsed != null ? parsed : new HashMap<>();
    }

    private void persist(Map<String, String> tokens)
    {
        configManager.setConfiguration("osrsjournal", "syncTokensJson", gson.toJson(tokens));
    }
}

